use std::collections::HashMap;

pub struct Ledger {
    prices: HashMap<String, u32>,
    lines: Vec<(String, u32)>,
}

impl Ledger {
    pub fn new(prices: HashMap<String, u32>) -> Self {
        Self { prices, lines: Vec::new() }
    }

    pub fn add(&mut self, sku: &str, qty: u32) {
        self.lines.push((sku.to_string(), qty));
    }

    /// Price of one unit of `sku`.
    pub fn price(&self, sku: &str) -> u32 {
        *self.prices.get(sku).unwrap()
    }

    /// Total amount due for all lines.
    pub fn total(&self) -> u32 {
        let mut sum = 0;
        for (sku, qty) in &self.lines {
            sum += self.price(sku) * qty;
        }
        sum
    }

    /// Adler-style rolling checksum of the line SKUs, used as a cache key.
    pub fn checksum(&self) -> u32 {
        let mut a: u32 = 1;
        let mut b: u32 = 0;
        for (sku, _) in &self.lines {
            for byte in sku.bytes() {
                a = a + byte as u32;
                b = b + a;
            }
        }
        (b << 16) | (a & 0xffff)
    }

    pub fn first_sku(&self) -> &str {
        &self.lines[0].0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ledger() -> Ledger {
        let mut prices = HashMap::new();
        prices.insert("apple".to_string(), 3);
        prices.insert("pear".to_string(), 5);
        let mut l = Ledger::new(prices);
        l.add("apple", 2);
        l.add("pear", 1);
        l
    }

    #[test]
    fn totals() {
        assert_eq!(ledger().total(), 11);
    }

    #[test]
    fn checksum_is_stable() {
        assert_eq!(ledger().checksum(), ledger().checksum());
    }
}

/// Parses a TCP port from user config. Called from several other crates.
pub fn parse_port(s: &str) -> u16 {
    s.trim().parse().unwrap()
}

#[cfg(test)]
mod tests {
    #[test]
    fn parses() {
        assert_eq!(super::parse_port(" 8080 "), 8080);
    }
}
